import test from 'node:test';
import assert from 'node:assert/strict';
import { mediaProviderConfig, assertMediaConfiguration, transcribeMedia, generateMediaJson, type MediaProviderConfig } from '../src/media-provider.js';
const config:MediaProviderConfig={baseUrl:'https://test.invalid/v1',apiKey:'test_not_real',model:'test_model',timeoutMs:1000};
test('media provider requires explicit configuration and confines fixtures to tests',()=>{
  assert.throws(()=>mediaProviderConfig('medical_ocr',{}),{code:'AI_NOT_CONFIGURED'});
  assert.throws(()=>mediaProviderConfig('medical_ocr',{GROWDESK_AI_PROVIDER:'fixture',GROWDESK_AI_FIXTURE_TEXT:'{}',NODE_ENV:'production'}),{code:'AI_NOT_CONFIGURED'});
  assert.throws(()=>assertMediaConfiguration('medical_ocr',{GROWDESK_AI_PROVIDER:'fixture',GROWDESK_AI_FIXTURE_TEXT:'{}',NODE_ENV:'test'}),{code:'STORAGE_NOT_CONFIGURED'});
  assert.equal(mediaProviderConfig('voice_transcription',{GROWDESK_AUDIO_BASE_URL:'https://test.invalid/v1',GROWDESK_AUDIO_API_KEY:'test_key',GROWDESK_AUDIO_MODEL:'test_audio'}).model,'test_audio');
});
for(const url of ['http://remote.invalid','https://user:password@test.invalid','https://test.invalid?key=secret','https://test.invalid#fragment']) {
  test(`reject unsafe configured endpoint ${new URL(url).hostname}`,()=>{
    assert.throws(()=>mediaProviderConfig('medical_ocr',{GROWDESK_AI_BASE_URL:url,GROWDESK_AI_API_KEY:'test_key',GROWDESK_AI_MODEL:'test_model'}),{code:'AI_INVALID_CONFIGURATION'});
  });
}
test('audio posts bounded multipart bytes once with the configured model',async t=>{
  let calls=0;
  t.mock.method(globalThis,'fetch',async(input:unknown,init?:RequestInit)=>{
    calls++;assert.equal(input,'https://test.invalid/v1/audio/transcriptions');assert.equal(init?.redirect,'error');
    assert.ok(init?.body instanceof FormData);assert.equal(init.body.get('model'),'test_model');
    const file=init.body.get('file');assert.ok(file instanceof Blob);assert.equal(await file.text(),'test_audio');
    assert.equal(new Headers(init.headers).get('content-type'),null,'fetch chooses the multipart boundary');
    return Response.json({text:'test_transcript'});
  });
  assert.equal(await transcribeMedia(Buffer.from('test_audio'),'audio/wav',config),'test_transcript');assert.equal(calls,1);
});
test('provider failure is not silently retried or replaced with a result',async t=>{
  let calls=0;t.mock.method(globalThis,'fetch',async()=>{calls++;return new Response('failure',{status:503});});
  await assert.rejects(transcribeMedia(Buffer.from('test_audio'),'audio/wav',config),{code:'AI_PROVIDER_HTTP_ERROR'});assert.equal(calls,1);
});
test('structured completion rejects missing, malformed and oversized responses',async t=>{
  const mock=t.mock.method(globalThis,'fetch',async()=>Response.json({choices:[{message:{content:'not-json'}}]}));
  await assert.rejects(generateMediaJson('test_prompt',config),{code:'AI_PROVIDER_INVALID_RESPONSE'});
  mock.mock.mockImplementation(async()=>new Response('x'.repeat(2_000_001)));
  await assert.rejects(generateMediaJson('test_prompt',config),{code:'AI_PROVIDER_RESPONSE_TOO_LARGE'});
});
test('audio validation happens before any network call',async t=>{
  t.mock.method(globalThis,'fetch',async()=>{throw new Error('Network must not be called');});
  await assert.rejects(transcribeMedia(new Uint8Array(),'audio/wav',config),{code:'INVALID_AUDIO_SIZE'});
  await assert.rejects(transcribeMedia(new Uint8Array([1]),'application/octet-stream',config),{code:'INVALID_AUDIO_TYPE'});
});

import { AiRunSchema,AiRunEventSchema } from "./ai.js";
import { Type, type Static } from "@sinclair/typebox";
import { UuidString, DateString, Nullable, DateTimeString } from "./common.js";
import type { RouteDefinition } from "./routes.js";
const Obj = <T extends Record<string, import("@sinclair/typebox").TSchema>>(fields: T) => Type.Object(fields, { additionalProperties: false });
export const WebJobKind = Type.Union([Type.Literal("medical_ocr"), Type.Literal("growth_ocr"), Type.Literal("voice_transcription"), Type.Literal("daily_summary_synthesis")]);
export const WebJobInput = Obj({ type: WebJobKind, babyId: UuidString, clientRequestId: UuidString, attachmentId: Type.Optional(UuidString), targetDate: Type.Optional(DateString) });
export type WebJobCreate = Static<typeof WebJobInput>;
export const WebJobSchema = Obj({
  id: UuidString, userId: UuidString, familyId: UuidString, babyId: UuidString, type: Type.String(),
  status: Type.Union([Type.Literal("pending"),Type.Literal("running"),Type.Literal("succeeded"),Type.Literal("failed"),Type.Literal("cancelled")]),
  resultJson: Nullable(Type.String()), errorMessage: Nullable(Type.String()), imageUrl: Nullable(Type.String()),
  claimed: Type.Boolean(), attempt: Type.Integer(), maxAttempts: Type.Integer(),
  createdAt: DateTimeString, startedAt: Nullable(DateTimeString), finishedAt: Nullable(DateTimeString),
});
export type WebJob = Static<typeof WebJobSchema>;
export const WebJobQuery = Obj({ type: Type.Optional(Type.String({maxLength:100})), babyId: Type.Optional(UuidString), limit: Type.Optional(Type.Integer({minimum:1,maximum:100,default:30})), offset: Type.Optional(Type.Integer({minimum:0,maximum:10000,default:0})) });
export type WebJobListQuery = Static<typeof WebJobQuery>;
export const VoiceLogInput = Obj({ id: UuidString, babyId: UuidString, prompt: Type.String({maxLength:200000}), reply: Type.String({maxLength:200000}), isAsync: Type.Boolean(), isFastPath: Type.Boolean(), acknowledged: Type.Optional(Type.Boolean()) });
export type WebVoiceLogInput = Static<typeof VoiceLogInput>;
export const VoiceLogSchema = Obj({ ...VoiceLogInput.properties, userId: UuidString, acknowledged: Type.Boolean(), createdAt: DateTimeString,
  baby: Obj({id:UuidString,nickname:Type.String(),gender:Type.Optional(Type.String())}) });
const id = Obj({id:UuidString});
const errors = Object.fromEntries([400,401,403,404,409,413,422,429,502,503].map(n=>[n,Obj({error:Obj({code:Type.String(),message:Type.String(),requestId:Type.String(),details:Type.Optional(Type.Unknown())})})]));
const response = (schema: import("@sinclair/typebox").TSchema, code=200) => ({[code]:Obj({data:schema}),...errors});
const common = { tags:["Web background"], implementationStatus:"READY" as const };
export const WEB_BACKGROUND_ROUTES: RouteDefinition[] = [
  { ...common, method:"POST",path:"/api/v1/web/ai/jobs",operationId:"createWebJob",summary:"Enqueue an authorized durable media task",body:WebJobInput,responses:response(WebJobSchema,202)},
  { ...common, method:"GET",path:"/api/v1/web/ai/jobs",operationId:"listWebJobs",summary:"List authoritative jobs",querystring:WebJobQuery,responses:response(Obj({pendingClaim:Type.Integer(),total:Type.Integer(),jobs:Type.Array(WebJobSchema)}))},
  { ...common, method:"GET",path:"/api/v1/web/ai/jobs/:id",operationId:"getWebJob",summary:"Read an authorized job",params:id,responses:response(WebJobSchema)},
  ...["claim","cancel","retry"].map(action=>({...common,method:"POST" as const,path:`/api/v1/web/ai/jobs/:id/${action}`,operationId:`${action}WebJob`,summary:`Explicitly ${action} a job`,params:id,...(action==="retry"?{body:Obj({commandId:UuidString})}:{}),responses:response(WebJobSchema)})),
  { ...common,method:"POST",path:"/api/v1/web/voice/logs",operationId:"createWebVoiceLog",summary:"Persist an authorized voice interaction",body:VoiceLogInput,responses:response(VoiceLogSchema,201)},
  { ...common,method:"GET",path:"/api/v1/web/voice/logs",operationId:"listWebVoiceLogs",summary:"Read authorized persisted voice interactions",querystring:Obj({limit:Type.Optional(Type.Integer({minimum:1,maximum:100,default:20})),unreadAsyncOnly:Type.Optional(Type.Boolean())}),responses:response(Obj({logs:Type.Array(VoiceLogSchema),unreadLog:Nullable(VoiceLogSchema)}))},
  { ...common,method:"GET",path:"/api/v1/web/voice/logs/:id",operationId:"getWebVoiceLog",summary:"Read an owned voice interaction",params:id,responses:response(VoiceLogSchema)},
  { ...common,method:"POST",path:"/api/v1/web/voice/logs/:id/acknowledge",operationId:"acknowledgeWebVoiceLog",summary:"Acknowledge an owned voice result",params:id,body:Obj({acknowledged:Type.Boolean()}),responses:response(Obj({acknowledged:Type.Boolean()}))},
  { ...common,method:"DELETE",path:"/api/v1/notifications/:id",operationId:"deleteWebNotification",summary:"Dismiss an owned notification",params:id,responses:response(Obj({success:Type.Literal(true)}))},
];

export const WebHistoryKind = Type.Union([Type.Literal("sessions"),Type.Literal("jobs"),Type.Literal("voiceLogs"),Type.Literal("notifications")]);
export const WebHistoryImportBody = Obj({kind:WebHistoryKind,record:Type.Record(Type.String(),Type.Unknown())});
export const WEB_HISTORY_ROUTES:RouteDefinition[]=[
  {...common,method:"POST",path:"/api/v1/web/history/import",operationId:"importWebHistory",summary:"Explicitly import one owned history record without overwriting authoritative data",body:WebHistoryImportBody,responses:response(Obj({sourceId:Type.String(),targetId:UuidString,payloadHash:Type.String(),alreadyImported:Type.Boolean()}))},
  {...common,method:"GET",path:"/api/v1/web/history/export",operationId:"exportWebHistory",summary:"Verify or recover an owned imported source record",querystring:Obj({kind:WebHistoryKind,sourceId:Type.String({minLength:1,maxLength:128})}),responses:response(Obj({record:Type.Record(Type.String(),Type.Unknown()),payloadHash:Type.String(),targetId:UuidString}))},
];

export const WEB_CHAT_READ_ROUTES:RouteDefinition[]=[
 {...common,method:"GET",path:"/api/v1/web/ai/sessions/:id/run",operationId:"latestWebChatRun",summary:"Read the latest owned durable chat run",params:id,responses:response(Nullable(AiRunSchema))},
 {...common,method:"GET",path:"/api/v1/web/ai/runs/:id/events",operationId:"readWebChatEvents",summary:"Read durable chat events without starting work",params:id,querystring:Obj({after:Type.Optional(Type.String({pattern:"^[0-9]+$"}))}),responses:response(Obj({status:Type.String(),terminal:Type.Boolean(),events:Type.Array(AiRunEventSchema)}))},
];
